using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;
public static class StudioEdgeGestureValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static StudioModelEditor ed;static StudioModelDocument doc;static SceneView view;static int checks,stage;static double next;static Vector2[] points;static string error,trace="";static Vector2 deliveredPointer;static int selectedOrange;
 static object Call(string n,params object[] a)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length&&m.GetParameters().Select((p,i)=>a[i]==null||p.ParameterType.IsInstanceOfType(a[i])).All(b=>b)).Invoke(ed,a);
 static object Get(string n)=>typeof(StudioModelEditor).GetField(n,F).GetValue(ed);static void Set(string n,object v)=>typeof(StudioModelEditor).GetField(n,F).SetValue(ed,v);static void Check(bool b,string m){checks++;if(!b)throw new Exception(m+"\n"+trace);}
 public static void Run(){EditorApplication.delayCall+=()=>{try{doc=ScriptableObject.CreateInstance<StudioModelDocument>();var m=new Mesh();m.vertices=new[]{new Vector3(-2,-1,0),new Vector3(0,-1,0),new Vector3(0,1,0),new Vector3(-2,1,0),new Vector3(0,-1,0),new Vector3(2,-1,0),new Vector3(2,1,0),new Vector3(0,1,0)};m.triangles=new[]{0,1,2,0,2,3,4,5,6,4,6,7};m.RecalculateNormals();m.RecalculateBounds();doc.nodes.Add(new StudioModelDocument.Node{name="Split attribute seam",mesh=m,cutPolygons=new[]{0,4,0,1,2,3,0,4,4,5,6,7},cutTriangles=m.triangles});ed=new StudioModelEditor(()=>view?.Repaint());ed.Load(doc);ed.SelectObject(0);ed.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Edge);Set("weld",true);Set("xray",false);Set("tool",Tool.None);view=ScriptableObject.CreateInstance<SceneView>();typeof(SceneView).GetProperty("customScene",F).SetValue(view,ed.Scene);view.position=new Rect(100,100,1000,750);view.Show();view.orthographic=true;view.LookAtDirect(Vector3.zero,Quaternion.identity,5);SceneView.duringSceneGui+=Scene;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}};}
 static void Scene(SceneView s){if(s!=view)return;try{points=new[]{new Vector3(-1,1,0),new Vector3(1,1,0),Vector3.zero}.Select(HandleUtility.WorldToGUIPoint).ToArray();if(Event.current.isMouse)deliveredPointer=Event.current.mousePosition;if(Event.current.isMouse)trace+=$"BEFORE {Event.current.type}: pointer={Event.current.mousePosition} expected={points[0]} component={Call("FindComponentAt",view,Event.current.mousePosition)} node={Call("MeshAtModePointer",view,Event.current.mousePosition)}\n";ed.SceneGUI(view,null);trace+=$"{Event.current.rawType}: hot={GUIUtility.hotControl} nearest={HandleUtility.nearestControl} marquee={Get("marquee")} selected={string.Join(",",ed.Components)}\n";}catch(Exception e){error=e.ToString();}}
 static void Click(Vector2 p,EventModifiers mods,int count=1,Vector2? jitter=null){view.SendEvent(new Event{type=EventType.MouseMove,mousePosition=p});p+=p-deliveredPointer;view.SendEvent(new Event{type=EventType.Layout,mousePosition=p});view.SendEvent(new Event{type=EventType.MouseDown,button=0,clickCount=count,mousePosition=p,modifiers=mods});if(jitter.HasValue)view.SendEvent(new Event{type=EventType.MouseDrag,button=0,mousePosition=p+jitter.Value,modifiers=mods});view.SendEvent(new Event{type=EventType.MouseUp,button=0,clickCount=count,mousePosition=p+(jitter??Vector2.zero),modifiers=mods});}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.15;try{if(error!=null)throw new Exception(error);if(points==null)return;
 if(stage<8){int i=stage%2;Click(points[i],EventModifiers.None);Check(ed.Components.Count==1,"Plain edge click must select exactly one edge at stage "+stage);Click(points[i],EventModifiers.Control);Check(ed.Components.Count==0,"Ctrl edge click must deselect immediately at stage "+stage);stage++;view.Repaint();return;}
 if(stage==8){Set("tool",Tool.Move);Click(points[0],EventModifiers.None);Check(ed.Components.Count==1,"Move tool plain edge click");Click(points[0],EventModifiers.Control);Check(ed.Components.Count==0,"Move tool Ctrl click");stage++;return;}
 if(stage==9){Set("tool",Tool.None);var edges=(List<(int a,int b)>)Call("Edges");var v=doc.nodes[0].mesh.vertices;var aliases=Enumerable.Range(0,edges.Count).Where(i=>v[edges[i].a].x==0&&v[edges[i].b].x==0).ToArray();Check(aliases.Length==2,"Seam setup");ed.Components.UnionWith(aliases);Click(points[2],EventModifiers.Control);Check(!aliases.Any(ed.Components.Contains),"Ctrl-click leaves a selected raw alias of the same visible edge");stage++;return;}
 if(stage==10){Set("tool",Tool.Move);Click(points[0],EventModifiers.None);var before=ed.ActiveMesh.vertices;Click(points[0],EventModifiers.Control,jitter:new Vector2(110,0));Check(!ed.ActiveMesh.vertices.SequenceEqual(before),"Ctrl-drag native gizmo still translates geometry");Check(ed.Components.Count>0,"Ctrl drag must not deselect on release");stage++;return;}
 if(stage==11){Set("tool",Tool.None);ed.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Edge);Click(points[1],EventModifiers.None);Check(ed.Components.Count==1,"Select edge before rendered check");stage++;view.Repaint();return;}
 if(stage==12){selectedOrange=Capture("selected");Check(selectedOrange>5,"Selected edge must actually render orange");Click(points[1],EventModifiers.Control);Check(ed.Components.Count==0,"Rendered edge native Ctrl deselect");stage++;view.Repaint();return;}
 if(stage==13){Check(Capture("deselected")<selectedOrange/2,"Deselected orange highlight must disappear on next repaint");UnityEditor.Undo.FlushUndoRecordObjects();ed.PerformWorkspaceHistory(false);Check(ed.Components.Count==1,"One Undo restores clicked selection");ed.PerformWorkspaceHistory(true);Check(ed.Components.Count==0,"Redo restores deselection");stage++;}
 Finish("PASS "+checks+" native press/release edge selection and deselection checks\n"+trace);
 }catch(Exception e){Finish(e.ToString());}}
 static int Capture(string name){var parent=typeof(EditorWindow).GetField("m_Parent",F).GetValue(view);int w=(int)view.position.width,h=(int)view.position.height;var rt=new RenderTexture(w,h,0);rt.Create();var old=RenderTexture.active;var t=new Texture2D(w,h,TextureFormat.RGBA32,false);try{parent.GetType().GetMethod("GrabPixels",F).Invoke(parent,new object[]{rt,new Rect(0,0,w,h)});RenderTexture.active=rt;t.ReadPixels(new Rect(0,0,w,h),0,0);t.Apply();var pixels=t.GetPixels32();var flipped=new Color32[pixels.Length];for(int y=0;y<h;y++)Array.Copy(pixels,y*w,flipped,(h-y-1)*w,w);t.SetPixels32(flipped);t.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../edge-gesture-"+name+".png")),t.EncodeToPNG());return pixels.Count(c=>c.r>180&&c.g>90&&c.g<220&&c.b<100);}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}}
 static void Finish(string s){EditorApplication.update-=Tick;SceneView.duringSceneGui-=Scene;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../edge-gesture-result.txt")),s);EditorApplication.delayCall+=()=>{if(view)view.Close();ed?.Dispose();EditorApplication.Exit(s.StartsWith("PASS")?0:1);};}
}
